<?php
declare(strict_types=1);

function sf_inquiry_json(array $v): string { return json_encode($v,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE) ?: '{}'; }
function sf_inquiry_decode(mixed $v,array $fallback=[]): array { $d=is_array($v)?$v:json_decode((string)$v,true);return is_array($d)?$d:$fallback; }
function sf_inquiry_types(): array { return ['booking','press','licensing','collaboration','general']; }
function sf_inquiry_statuses(): array { return ['new','reviewing','replied','closed','spam']; }
function sf_inquiry_type_label(string $type): string { return ['booking'=>'Booking / live','press'=>'Press / media','licensing'=>'Licensing / sync','collaboration'=>'Collaboration','general'=>'General inquiry'][$type]??'Professional inquiry'; }
function sf_inquiry_reference(int $id): string { return 'SFQ-'.str_pad((string)$id,6,'0',STR_PAD_LEFT); }
function sf_inquiry_https_url(string $url): bool { return $url===''||((bool)filter_var($url,FILTER_VALIDATE_URL)&&strtolower((string)parse_url($url,PHP_URL_SCHEME))==='https'); }
function sf_inquiry_source_path(string $raw): string {
    $raw=trim($raw);if($raw==='')return '';
    $path=(string)(parse_url($raw,PHP_URL_PATH)??$raw);if($path===''||$path[0]!=='/')$path='/'.ltrim($path,'/');
    return sf_clean_text($path,240);
}
function sf_inquiry_clean_email(string $email): string { return strtolower(trim($email)); }
function sf_inquiry_clean_body(mixed $v,int $max=6000): string {
    $s=str_replace(["\r\n","\r"],"\n",(string)$v);$s=preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u','',$s)??'';$s=trim($s);
    return function_exists('mb_substr')?mb_substr($s,0,$max):substr($s,0,$max);
}

function sf_inquiry_ensure_schema(): void {
    static $done=false;if($done)return;$pdo=sf_db();$driver=(string)(sf_db_config()['driver']??'');
    if($driver==='sqlite'){
        $pdo->exec("CREATE TABLE IF NOT EXISTS professional_inquiries (id INTEGER PRIMARY KEY AUTOINCREMENT,inquiry_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',name TEXT NOT NULL,email TEXT NOT NULL,organization TEXT NOT NULL DEFAULT '',website_url TEXT NOT NULL DEFAULT '',subject TEXT NOT NULL,message_text TEXT NOT NULL,event_date TEXT NULL,location TEXT NOT NULL DEFAULT '',track_id TEXT NOT NULL DEFAULT '',release_id TEXT NOT NULL DEFAULT '',source_path TEXT NOT NULL DEFAULT '',consent_contact INTEGER NOT NULL DEFAULT 1,fingerprint_sha256 TEXT NOT NULL,internal_notes TEXT NOT NULL DEFAULT '',last_replied_at TEXT NULL,closed_at TEXT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)");
        $pdo->exec("CREATE INDEX IF NOT EXISTS idx_professional_inquiries_status ON professional_inquiries(status,inquiry_type,created_at)");
        $pdo->exec("CREATE INDEX IF NOT EXISTS idx_professional_inquiries_email ON professional_inquiries(email,created_at)");
        $pdo->exec("CREATE INDEX IF NOT EXISTS idx_professional_inquiries_fingerprint ON professional_inquiries(fingerprint_sha256,created_at)");
        $pdo->exec("CREATE TABLE IF NOT EXISTS professional_inquiry_messages (id INTEGER PRIMARY KEY AUTOINCREMENT,inquiry_id INTEGER NOT NULL,direction TEXT NOT NULL,subject TEXT NOT NULL,body_text TEXT NOT NULL,status TEXT NOT NULL,delivery_id INTEGER NULL,error_text TEXT NOT NULL DEFAULT '',created_by INTEGER NULL,created_at TEXT NOT NULL,FOREIGN KEY(inquiry_id) REFERENCES professional_inquiries(id) ON DELETE CASCADE,FOREIGN KEY(delivery_id) REFERENCES transactional_email_outbox(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL)");
        $pdo->exec("CREATE INDEX IF NOT EXISTS idx_professional_inquiry_messages ON professional_inquiry_messages(inquiry_id,created_at)");
        $pdo->exec("CREATE TABLE IF NOT EXISTS professional_inquiry_events (id INTEGER PRIMARY KEY AUTOINCREMENT,inquiry_id INTEGER NOT NULL,event_type TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',created_by INTEGER NULL,created_at TEXT NOT NULL,FOREIGN KEY(inquiry_id) REFERENCES professional_inquiries(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL)");
        $pdo->exec("CREATE INDEX IF NOT EXISTS idx_professional_inquiry_events ON professional_inquiry_events(inquiry_id,event_type,created_at)");
    }else{
        $pdo->exec("CREATE TABLE IF NOT EXISTS professional_inquiries (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,inquiry_type VARCHAR(40) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'new',name VARCHAR(180) NOT NULL,email VARCHAR(190) NOT NULL,organization VARCHAR(220) NOT NULL DEFAULT '',website_url VARCHAR(700) NOT NULL DEFAULT '',subject VARCHAR(255) NOT NULL,message_text LONGTEXT NOT NULL,event_date VARCHAR(40) NULL,location VARCHAR(255) NOT NULL DEFAULT '',track_id VARCHAR(160) NOT NULL DEFAULT '',release_id VARCHAR(160) NOT NULL DEFAULT '',source_path VARCHAR(240) NOT NULL DEFAULT '',consent_contact TINYINT(1) NOT NULL DEFAULT 1,fingerprint_sha256 CHAR(64) NOT NULL,internal_notes LONGTEXT NOT NULL,last_replied_at VARCHAR(40) NULL,closed_at VARCHAR(40) NULL,created_at VARCHAR(40) NOT NULL,updated_at VARCHAR(40) NOT NULL,INDEX idx_professional_inquiries_status(status,inquiry_type,created_at),INDEX idx_professional_inquiries_email(email,created_at),INDEX idx_professional_inquiries_fingerprint(fingerprint_sha256,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $pdo->exec("CREATE TABLE IF NOT EXISTS professional_inquiry_messages (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,inquiry_id BIGINT UNSIGNED NOT NULL,direction VARCHAR(16) NOT NULL,subject VARCHAR(255) NOT NULL,body_text LONGTEXT NOT NULL,status VARCHAR(32) NOT NULL,delivery_id BIGINT UNSIGNED NULL,error_text TEXT NOT NULL,created_by BIGINT UNSIGNED NULL,created_at VARCHAR(40) NOT NULL,INDEX idx_professional_inquiry_messages(inquiry_id,created_at),CONSTRAINT fk_prof_inquiry_msg FOREIGN KEY(inquiry_id) REFERENCES professional_inquiries(id) ON DELETE CASCADE,CONSTRAINT fk_prof_inquiry_delivery FOREIGN KEY(delivery_id) REFERENCES transactional_email_outbox(id) ON DELETE SET NULL,CONSTRAINT fk_prof_inquiry_msg_admin FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
        $pdo->exec("CREATE TABLE IF NOT EXISTS professional_inquiry_events (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,inquiry_id BIGINT UNSIGNED NOT NULL,event_type VARCHAR(50) NOT NULL,detail_json LONGTEXT NOT NULL,created_by BIGINT UNSIGNED NULL,created_at VARCHAR(40) NOT NULL,INDEX idx_professional_inquiry_events(inquiry_id,event_type,created_at),CONSTRAINT fk_prof_inquiry_event FOREIGN KEY(inquiry_id) REFERENCES professional_inquiries(id) ON DELETE CASCADE,CONSTRAINT fk_prof_inquiry_event_admin FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    }
    $done=true;
}
function sf_inquiry_event(int $id,string $type,array $detail=[],int $adminId=0): void {
    sf_inquiry_ensure_schema();$safe=[];foreach(array_slice($detail,0,12,true) as $k=>$v)$safe[sf_clean_text((string)$k,60)]=is_scalar($v)?sf_clean_text((string)$v,400):'';
    sf_db()->prepare('INSERT INTO professional_inquiry_events(inquiry_id,event_type,detail_json,created_by,created_at) VALUES(?,?,?,?,?)')->execute([$id,sf_clean_text($type,50),sf_inquiry_json($safe),$adminId?:null,gmdate('c')]);
}
function sf_inquiry_get(int $id): ?array {
    sf_inquiry_ensure_schema();$q=sf_db()->prepare('SELECT * FROM professional_inquiries WHERE id=?');$q->execute([$id]);$r=$q->fetch();if(!$r)return null;$r['reference']=sf_inquiry_reference($id);$r['consent_contact']=!empty($r['consent_contact']);
    $q=sf_db()->prepare('SELECT id,direction,subject,body_text,status,delivery_id,error_text,created_by,created_at FROM professional_inquiry_messages WHERE inquiry_id=? ORDER BY id ASC');$q->execute([$id]);$r['messages']=$q->fetchAll();
    $q=sf_db()->prepare('SELECT id,event_type,detail_json,created_by,created_at FROM professional_inquiry_events WHERE inquiry_id=? ORDER BY id DESC');$q->execute([$id]);$events=$q->fetchAll();foreach($events as &$e){$e['detail']=sf_inquiry_decode($e['detail_json']??'',[]);unset($e['detail_json']);}unset($e);$r['events']=$events;return $r;
}
function sf_inquiry_list(string $status='',string $type='',string $q='',int $limit=300): array {
    sf_inquiry_ensure_schema();$where=[];$args=[];if($status!==''&&in_array($status,sf_inquiry_statuses(),true)){$where[]='status=?';$args[]=$status;}if($type!==''&&in_array($type,sf_inquiry_types(),true)){$where[]='inquiry_type=?';$args[]=$type;}if($q!==''){$where[]='(name LIKE ? OR email LIKE ? OR organization LIKE ? OR subject LIKE ?)';$like='%'.sf_clean_text($q,120).'%';array_push($args,$like,$like,$like,$like);}
    $sql='SELECT id,inquiry_type,status,name,email,organization,subject,event_date,location,track_id,release_id,source_path,last_replied_at,closed_at,created_at,updated_at FROM professional_inquiries'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY CASE status WHEN \'new\' THEN 0 WHEN \'reviewing\' THEN 1 WHEN \'replied\' THEN 2 WHEN \'closed\' THEN 3 ELSE 4 END, id DESC LIMIT '.max(1,min(500,$limit));$st=sf_db()->prepare($sql);$st->execute($args);$rows=$st->fetchAll();foreach($rows as &$r)$r['reference']=sf_inquiry_reference((int)$r['id']);unset($r);return $rows;
}
function sf_inquiry_summary(): array {
    sf_inquiry_ensure_schema();$pdo=sf_db();$by=[];foreach($pdo->query('SELECT status,COUNT(*) total FROM professional_inquiries GROUP BY status')->fetchAll() as $r)$by[(string)$r['status']]=(int)$r['total'];$types=[];foreach($pdo->query("SELECT inquiry_type,COUNT(*) total FROM professional_inquiries WHERE status NOT IN ('closed','spam') GROUP BY inquiry_type")->fetchAll() as $r)$types[(string)$r['inquiry_type']]=(int)$r['total'];
    return ['total'=>(int)$pdo->query('SELECT COUNT(*) FROM professional_inquiries')->fetchColumn(),'new'=>$by['new']??0,'reviewing'=>$by['reviewing']??0,'replied'=>$by['replied']??0,'closed'=>$by['closed']??0,'spam'=>$by['spam']??0,'open'=>($by['new']??0)+($by['reviewing']??0),'types'=>$types];
}
function sf_inquiry_public_references(): array {
    $tracks=[];if(function_exists('sf_seo_public_track'))foreach(sf_catalog() as $t){$id=(string)($t['id']??'');if($id!==''&&sf_seo_public_track($id))$tracks[]=['id'=>$id,'title'=>(string)($t['title']??$id),'release'=>(string)($t['release']??'')];}
    $releases=[];if(function_exists('sf_seo_release_rows'))foreach(sf_seo_release_rows() as $r)if(($r['state']??'published')==='published'&&($r['public_visible']??true)!==false&&!empty($r['id']))$releases[]=['id'=>(string)$r['id'],'title'=>(string)($r['title']??$r['id']),'date'=>(string)($r['release_date']??'')];
    return ['tracks'=>$tracks,'releases'=>$releases];
}
function sf_inquiry_validate_entity(string $trackId,string $releaseId): void {
    if($trackId!==''&&(!function_exists('sf_seo_public_track')||!sf_seo_public_track($trackId)))throw new InvalidArgumentException('Selected song is not publicly available.');
    if($releaseId!==''&&(!function_exists('sf_seo_public_release')||!sf_seo_public_release($releaseId)))throw new InvalidArgumentException('Selected release is not publicly available.');
}
function sf_inquiry_submit(array $raw): array {
    sf_inquiry_ensure_schema();$type=(string)($raw['inquiry_type']??'general');if(!in_array($type,sf_inquiry_types(),true))throw new InvalidArgumentException('Choose a valid inquiry type.');
    $name=sf_clean_text($raw['name']??'',180);$email=sf_inquiry_clean_email((string)($raw['email']??''));$org=sf_clean_text($raw['organization']??'',220);$website=sf_clean_text($raw['website_url']??'',700);$subject=sf_clean_text($raw['subject']??'',255);$message=sf_inquiry_clean_body($raw['message_text']??'',6000);
    if((function_exists('mb_strlen')?mb_strlen($name):strlen($name))<2)throw new InvalidArgumentException('Your name is required.');if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Enter a valid email address.');if(!sf_inquiry_https_url($website))throw new InvalidArgumentException('Website URL must use HTTPS.');if((function_exists('mb_strlen')?mb_strlen($subject):strlen($subject))<3)throw new InvalidArgumentException('Add a short subject.');if((function_exists('mb_strlen')?mb_strlen($message):strlen($message))<20)throw new InvalidArgumentException('Please include enough detail to evaluate the inquiry.');if(substr_count(strtolower($message),'http://')+substr_count(strtolower($message),'https://')>5)throw new InvalidArgumentException('Please limit external links in the message.');if(empty($raw['consent_contact']))throw new InvalidArgumentException('Confirm that Stonefellow may contact you about this inquiry.');
    $eventDate=trim((string)($raw['event_date']??''));if($eventDate!==''&&strtotime($eventDate)===false)throw new InvalidArgumentException('Event date is invalid.');
    $location=sf_clean_text($raw['location']??'',255);$trackId=sf_clean_text($raw['track_id']??'',160);$releaseId=sf_clean_text($raw['release_id']??'',160);sf_inquiry_validate_entity($trackId,$releaseId);$source=sf_inquiry_source_path((string)($raw['source_path']??''));
    $fingerprint=hash('sha256',$type.'|'.$email.'|'.strtolower($subject).'|'.$message);$cutoff=gmdate('c',time()-900);$q=sf_db()->prepare('SELECT id FROM professional_inquiries WHERE fingerprint_sha256=? AND created_at>=? ORDER BY id DESC LIMIT 1');$q->execute([$fingerprint,$cutoff]);$duplicate=(int)($q->fetchColumn()?:0);if($duplicate)return ['id'=>$duplicate,'reference'=>sf_inquiry_reference($duplicate),'duplicate'=>true];
    $now=gmdate('c');$q=sf_db()->prepare("INSERT INTO professional_inquiries(inquiry_type,status,name,email,organization,website_url,subject,message_text,event_date,location,track_id,release_id,source_path,consent_contact,fingerprint_sha256,internal_notes,last_replied_at,closed_at,created_at,updated_at) VALUES(?,'new',?,?,?,?,?,?,?,?,?,?,?,1,?,'',NULL,NULL,?,?)");$q->execute([$type,$name,$email,$org,$website,$subject,$message,$eventDate!==''?$eventDate:null,$location,$trackId,$releaseId,$source,$fingerprint,$now,$now]);$id=(int)sf_db()->lastInsertId();
    sf_db()->prepare("INSERT INTO professional_inquiry_messages(inquiry_id,direction,subject,body_text,status,delivery_id,error_text,created_by,created_at) VALUES(?,'inbound',?,?,'received',NULL,'',NULL,?)")->execute([$id,$subject,$message,$now]);sf_inquiry_event($id,'submitted',['type'=>$type,'source_path'=>$source]);return ['id'=>$id,'reference'=>sf_inquiry_reference($id),'duplicate'=>false];
}
function sf_inquiry_transition(int $id,string $status,int $adminId): array {
    if(!in_array($status,sf_inquiry_statuses(),true))throw new InvalidArgumentException('Invalid inquiry status.');$r=sf_inquiry_get($id);if(!$r)throw new InvalidArgumentException('Inquiry not found.');$from=(string)$r['status'];if($status===$from)return $r;if($status==='replied')throw new RuntimeException('Replied status is set only after a confirmed email is actually sent.');
    $allowed=['new'=>['reviewing','closed','spam'],'reviewing'=>['new','closed','spam'],'replied'=>['reviewing','closed'],'closed'=>['reviewing'],'spam'=>['reviewing']];if(!in_array($status,$allowed[$from]??[],true))throw new RuntimeException('That inquiry status transition is not allowed.');
    $now=gmdate('c');$closed=$status==='closed'?$now:null;sf_db()->prepare('UPDATE professional_inquiries SET status=?,closed_at=?,updated_at=? WHERE id=?')->execute([$status,$closed,$now,$id]);sf_inquiry_event($id,'status_changed',['from'=>$from,'to'=>$status],$adminId);return sf_inquiry_get($id)?:[];
}
function sf_inquiry_save_notes(int $id,string $notes,int $adminId): array {
    if(!sf_inquiry_get($id))throw new InvalidArgumentException('Inquiry not found.');$notes=sf_inquiry_clean_body($notes,12000);sf_db()->prepare('UPDATE professional_inquiries SET internal_notes=?,updated_at=? WHERE id=?')->execute([$notes,gmdate('c'),$id]);sf_inquiry_event($id,'notes_updated',['length'=>strlen($notes)],$adminId);return sf_inquiry_get($id)?:[];
}
function sf_inquiry_reply(int $id,string $subject,string $body,int $adminId): array {
    $r=sf_inquiry_get($id);if(!$r)throw new InvalidArgumentException('Inquiry not found.');if(in_array((string)$r['status'],['spam','closed'],true))throw new RuntimeException('Reopen this inquiry before replying.');$subject=sf_clean_text($subject,255);$body=sf_inquiry_clean_body($body,30000);if($subject===''||$body==='')throw new InvalidArgumentException('Reply subject and message are required.');
    $now=gmdate('c');$q=sf_db()->prepare("INSERT INTO professional_inquiry_messages(inquiry_id,direction,subject,body_text,status,delivery_id,error_text,created_by,created_at) VALUES(?,'outbound',?,?,'sending',NULL,'',?,?)");$q->execute([$id,$subject,$body,$adminId?:null,$now]);$mid=(int)sf_db()->lastInsertId();$delivery=['id'=>null,'status'=>'failed'];$status='failed';$deliveryId=null;$error='';
    try{$delivery=sf_transactional_email(0,(string)$r['email'],$subject,$body,'professional_inquiry_reply');$status=(string)($delivery['status']??'failed');$deliveryId=!empty($delivery['id'])?(int)$delivery['id']:null;if($deliveryId){$dq=sf_db()->prepare('SELECT status,error_text FROM transactional_email_outbox WHERE id=?');$dq->execute([$deliveryId]);$dr=$dq->fetch();if($dr){$status=(string)($dr['status']??$status);$error=sf_clean_text($dr['error_text']??'',1000);}}}catch(Throwable $e){$error=sf_clean_text($e->getMessage(),1000);$status='failed';}
    if(!in_array($status,['sent','queued','logged','failed'],true))$status='failed';sf_db()->prepare('UPDATE professional_inquiry_messages SET status=?,delivery_id=?,error_text=? WHERE id=?')->execute([$status,$deliveryId,$error,$mid]);$newStatus=$status==='sent'?'replied':((string)$r['status']==='new'?'reviewing':(string)$r['status']);$repliedAt=$status==='sent'?gmdate('c'):(string)($r['last_replied_at']??'');sf_db()->prepare('UPDATE professional_inquiries SET status=?,last_replied_at=?,closed_at=NULL,updated_at=? WHERE id=?')->execute([$newStatus,$repliedAt!==''?$repliedAt:null,gmdate('c'),$id]);sf_inquiry_event($id,$status==='sent'?'reply_sent':'reply_'.$status,['message_id'=>$mid,'delivery_id'=>$deliveryId?:0,'error'=>$error],$adminId);return ['inquiry'=>sf_inquiry_get($id),'delivery'=>$delivery];
}
